update content_bodies set title = '[Niseko, Hokkaido] Enjoying Home Time with Niseko ① - The Daruma Project Fun for Kids - A Staycation in an Unusual Everyday Life | Niseko Summer Stay (Kutchan Tourism Association)', description = 'This is a channel recommending summer stays in Niseko, Hokkaido!
This channel is operated by the Kutchan Tourism Association located in the Niseko area of Hokkaido.

Given the current situation, it is not possible to travel for tourism, but I hope that when the coronavirus situation calms down and the time comes to "travel!", "Niseko, Hokkaido" will be one of the options.

In this video, we introduce the Daruma Project that you can enjoy at home with Niseko.
Kiyoegallery Niseko''s Kiyo Hosokawa has come as a guest!
What is the Daruma Project?
What does Daruma mean?
What is the reaction of foreigners seeing Daruma?
And I actually tried it too!
If you would like to join, please feel free to download and use it here:
https://drive.google.com/file/d/1OHNufAMMHfkz78GJsyt53ps0Fro8vbbP/view

The Niseko area in Hokkaido is famous for winter, but summer is also highly recommended! To convey the "charm of summer in Niseko," this channel was created. This is an introductory video, but we plan to upload more videos, so I would be happy if you could subscribe to the channel.

○ Daruma Project
https://drive.google.com/file/d/1GaYMNK-2wd8q2_2oTPzFI_qMZro-MWdF/view
