〜『いちき串木野スマイルさんぽ』とは？〜

『いちき串木野市総合観光案内所YouTubeチャンネル』の新コンテンツ始動！

https://youtube.com/channel/UCFCiZgh28-RGRZ2L8seUqWg

竹どん＆パティシエールAYAの愉快な〈でこぼこコンビ〉がいちき串木野市に住む伝説の妖怪探しに奮闘する物語。
 
新型コロナウイルスの影響で失業して地元に帰ってきたパティシエールAYA。状況が落ち着くまでNPO法人鹿児島いちき串木野観光物産センターでお世話になることに。

https://ichiki-kushikino.com

「パティシエールならではの視点で地元の観光を盛り上げたい！出来ることは何だってしよう！」

ということで、いちき串木野市総合観光案内所の職員であり、タレント⁈の竹どんを巻き込んで活動しています。

https://mobile.twitter.com/takedon94

〈お菓子な視点〉で毎月いちき串木野市の旬の農産物をPRする『1日限りのお菓子屋さん』。

その売上金を利用していちき串木野市の人・物・食・体験をPRする『スマイルプロジェクト』。

そして今回、色々な規制がある中でも子供たちに楽しんでもらいたいということで、いちき串木野市に住む伝説の妖怪探しをする『いちき串木野スマイルさんぽ』。

「私たちと関わる人々を笑顔に！」

をモットーに活動していきますので、これからもよろしくお願いします。

#スマイルさんぽ
#スマイルプロジェクト
#1日限りのお菓子屋さん
