update content_bodies set title = '[Smile Walk] Exploring the Yokai (13) Ushi-Oni! Lots of Cows in Ichiki-Kushikino City!! (Taro Taro Festival Edition) [Ichiki-Kushikino City]', description = 'On a certain day in September 2021, despite the bad weather, Director AYA and her unwilling servant TKDN pushed through with the shoot due to scheduling conflicts. They arrived at Hashimasaki Shrine, where a festival related to cows is held, in search of the ''Ushi-Oni.'' At this time, neither of them realized that the shoot would turn out to be surprisingly long and grueling, so both are in a strange mood, but please enjoy! Haha

