~ What is ''Ichiki-Kushikino Smile Walk''? ~

A new content launch from the ''Ichiki-Kushikino City General Tourism Information Center YouTube Channel''!

https://youtube.com/channel/UCFCiZgh28-RGRZ2L8seUqWg

The delightful ''bumpy duo'' of Take-don and patissière AYA are on a quest to find legendary yokai living in Ichiki-Kushikino City.

Patissière AYA returned to her hometown after losing her job due to the impact of the COVID-19 pandemic. Until the situation stabilizes, she will be supported by the NPO Kagoshima Ichiki-Kushikino Tourism and Product Center.

https://ichiki-kushikino.com

''I want to promote local tourism from a patissière''s perspective! I''ll do whatever I can!''

With that in mind, she is collaborating with Take-don, an employee of the Ichiki-Kushikino City General Tourism Information Center and a talent?!

https://mobile.twitter.com/takedon94

With a ''sweets perspective,'' they promote seasonal agricultural products from Ichiki-Kushikino City through a ''one-day-only sweet shop.''

The proceeds from this will be used to promote the people, goods, food, and experiences of Ichiki-Kushikino City through the ''Smile Project.''

And this time, even with various restrictions, they want to bring joy to children by searching for legendary yokai living in Ichiki-Kushikino City through ''Ichiki-Kushikino Smile Walk.''

''We aim to make everyone we interact with smile!''

We will continue our activities with this motto, so please support us moving forward.

#SmileWalk
#SmileProject
#OneDayOnlySweetShop
#IchikiKushikinoYokaiMap
#PatissièreAYA
#ApprenticeTKDN
#UshiOni
#TaroTaroFestival
#HashimasakiShrine
#GonzaShrine
#IchikiKushikinoCity
#MinatoIroRomanTrip
#Don''tLoseToCorona
#NoWar' where id = '-e6rCee12drpPlfuvqMCB';
update content_bodies set title = '【スマイルさんぽ】妖怪⑩アモーレ！モレンビ（亡霊の火）！！【いちき串木野市】', description = '最近、九州テレビ局6局ネットでその取り組みが「二刀流」として取り上げられたパティシエールAYA監督。しかしYouTubeの監督業を加えると、その実「三刀流」になるんですけどね！笑

AYA監督のマルチな才能に振り回され、「1分1秒に至るまで」スケジュール管理されている見習いTKDNの生き様をぜひご覧ください！！笑笑

