~ What is ''Ichiki Kushikino Smile Walk''? ~

A new content launch on the ''Ichiki Kushikino City General Tourism Information Center YouTube Channel''!

https://youtube.com/channel/UCFCiZgh28-RGRZ2L8seUqWg

The delightful ''bumpy duo'' of Take-don and pastry chef AYA are on a quest to find legendary yokai living in Ichiki Kushikino City.

Pastry chef AYA returned to her hometown after losing her job due to the impact of the COVID-19 pandemic. Until the situation stabilizes, she will be taken care of by the NPO Kagoshima Ichiki Kushikino Tourism and Product Center.

https://ichiki-kushikino.com

''I want to promote local tourism from a pastry chef''s perspective! I''ll do whatever I can!''

With that in mind, we are involving Take-don, who is a staff member of the Ichiki Kushikino City General Tourism Information Center and a talent?!

https://mobile.twitter.com/takedon94

With a ''sweet perspective'', we promote seasonal agricultural products from Ichiki Kushikino City through a ''one-day-only sweet shop''.

The proceeds from sales are used to promote the people, goods, food, and experiences of Ichiki Kushikino City through the ''Smile Project''.

And this time, even with various restrictions, we want to bring joy to children, so we are conducting the ''Ichiki Kushikino Smile Walk'' to search for legendary yokai living in Ichiki Kushikino City.

''We aim to make everyone we interact with smile!''

We will continue our activities with this motto, so we appreciate your support moving forward.

