竹どん＆パティシエールAYAの愉快な〈でこぼこコンビ〉がいちき串木野市に住む伝説の妖怪探しに奮闘する物語。
 
新型コロナウイルスの影響で失業して地元に帰ってきたパティシエールAYA。状況が落ち着くまでNPO法人鹿児島いちき串木野観光物産センターでお世話になることに。

