~ What is ''Ichiki Kushikino Smile Walk''? ~

A new content launch from the ''Ichiki Kushikino City General Tourism Information Center YouTube Channel''!

https://youtube.com/channel/UCFCiZgh28-RGRZ2L8seUqWg

The delightful ''bumpy duo'' of Takendon and Patissier AYA are struggling to find legendary yokai living in Ichiki Kushikino City.

Patissier AYA returned to her hometown after losing her job due to the impact of the COVID-19 pandemic. Until the situation stabilizes, she will be taken care of by the NPO Kagoshima Ichiki Kushikino Tourism and Product Center.

https://ichiki-kushikino.com

''I want to liven up local tourism from a patissier''s perspective! I''ll do whatever I can!''

