https://mobile.twitter.com/takedon94

With a ''sweet perspective'', we promote seasonal agricultural products from Ichiki Kushikino City every month through a ''one-day-only sweet shop''.

The sales proceeds are used to promote the people, goods, food, and experiences of Ichiki Kushikino City through the ''Smile Project''.

And this time, even with various restrictions, we want children to have fun, so we are searching for legendary yokai living in Ichiki Kushikino City with the ''Ichiki Kushikino Smile Walk''.

''We will make the people we interact with smile!''

We will continue our activities with this motto, so we appreciate your support in the future.

