update content_bodies set title = '[Ichiki-Kushikino City] Ikki Gion Festival [Air Stroll]', description = 'The origin of the Ikki Gion Festival dates back to the 9th year of the Bunka era (1812) when the Yasaka Shrine in Ikki was built, and it is believed to have flourished during the time when Minato Town was a commercial port and post town. The sight of the lively male float and the elegantly adorned female float parading through the streets is a must-see.' where id = 'qQjXaFpbH7eBJ48uGkKLX';
