update content_bodies set title = '真KAGAWA 統合版', description = '今回のうどん県プロモーション動画では、「真・KAGAWA – Authentic KAGAWA -」をテーマに、「深」「心」「新」「浸」のキーワードに沿った「真の香川＝本物の香川」をご紹介。また、書を鑑賞することや、書道パフォーマンスなど日本人の心を震わせるコンテンツである日本文化（書道）を組み入れていますので、”心を震わせる感動”にご共感いただけます。

「真・KAGAWA」および「深」「心」「新」「浸」の文字を、書道家の郷祥（ごうしょう）氏に揮毫いただきました。

●書道家　郷祥（ごうしょう）
https://www.instagram.com/artist_goshow/
https://www.facebook.com/goshow88/' where id = '4UwOYUoTJoAAueJ1POq3B';
update content_bodies set title = 'True KAGAWA Integrated Edition', description = 'In this promotional video for the Udon Prefecture, we introduce ''True KAGAWA - Authentic KAGAWA -'' with the theme based on the keywords ''Deep'', ''Heart'', ''New'', and ''Immerse'', showcasing ''True Kagawa = Real Kagawa''. Additionally, we incorporate Japanese culture (calligraphy) that resonates with the hearts of the Japanese people through content such as appreciating calligraphy and calligraphy performances, allowing you to share in the ''emotional resonance that touches the heart''.

The characters for ''True KAGAWA'' and ''Deep'', ''Heart'', ''New'', and ''Immerse'' were beautifully written by calligrapher Goshō.

● Calligrapher Goshō
https://www.instagram.com/artist_goshow/
https://www.facebook.com/goshow88/' where id = 'aTD6wGBMIOrucyUQLmq50';
update content_bodies set title = '宇多津町のヤドンのデザインのマンホール（『ポケふた』）除幕式　令和２年８月１０日（月・祝）「ヤドンの日」', description = '令和２年８月１０日「ヤドンの日」に、宇多津町のヤドンのデザインのマンホール（『ポケふた』）除幕式が開催されました。
宇多津町の設置により、香川県内のすべての市町に、『ポケふた』が設置されました。

除幕式には、ヤドンとガラルヤドンが登場し、うどん県PR団として、マンホールの設置をお祝いしました。

©2020 Pokémon. ©1995-2020 Nintendo / Creatures Inc. / GAME FREAK inc.
ポケットモンスター・ポケモン・Pokémonは任天堂・クリーチャーズ・ゲームフリークの登録商標です。' where id = 'UIkDGIwSvmEOrhOhdBYZX';
update content_bodies set title = 'Unveiling Ceremony of the Yadon Design Manhole in Utazu Town (''Poke Futa'') on August 10, 2020 (Monday, Holiday) ''Yadon Day''', description = 'On August 10, 2020, ''Yadon Day'', the unveiling ceremony of the Yadon design manhole (''Poke Futa'') in Utazu Town was held.
With the installation in Utazu Town, ''Poke Futa'' has been installed in all cities and towns in Kagawa Prefecture.

At the unveiling ceremony, Yadon and Galarian Yadon made an appearance, celebrating the installation of the manhole as part of the Udon Prefecture PR group.

