update content_bodies set title = 'かがわ極上休日　沙弥島・瀬戸大橋', description = '瀬戸大橋を間近に見る、陸続きの島。瀬戸大橋には多くの島々が連なっており、沙弥島もその一つ。様々なロケーションで瀬戸内海と壮大な建築美を持つ瀬戸大橋を楽しめ、そのハーモニーを味わうことができます。
その他の映像はこちら！→http://www.my-kagawa.jp/udon-ken/shimatabi.html' where id = 'JcTDC67xvhZNRo0hFdVWc';
update content_bodies set title = 'Kagawa''s Ultimate Holiday: Shodoshima Island and the Seto Ohashi Bridge', description = 'A land-connected island where you can see the Seto Ohashi Bridge up close. The Seto Ohashi Bridge connects many islands, and Shodoshima is one of them. You can enjoy the Seto Inland Sea and the magnificent architectural beauty of the Seto Ohashi Bridge in various locations, experiencing their harmony.
For more videos, click here! → http://www.my-kagawa.jp/udon-ken/shimatabi.html' where id = 'g-d4lBnLVyH6GU8nJtAFu';
update content_bodies set title = 'かがわ極上休日　粟島・志々島・伊吹島・荘内半島', description = 'アーティストたちのアート作品に加え、島の人たちによるマイアートを楽しめる粟島。樹齢１２００年の大楠が島の神秘を物語る志々島。伊吹イリコで有名な、活気ある漁師たちの伊吹島。多島美を楽しむことができる、紺碧の瀬戸内海に突き出した荘内半島。同じ瀬戸内海の島々でも、それぞれ異なる魅力を楽しむことができます。
その他の映像はこちら！→http://www.my-kagawa.jp/udon-ken/shimatabi.html' where id = 'Mty7gdeA5Jo_6kQ5Fricn';
update content_bodies set title = 'Kagawa''s Ultimate Holiday: Awashima, Shishijima, Ibukijima, and Shonai Peninsula', description = 'Awashima, where you can enjoy the art of artists as well as the my art created by the island''s residents. Shishijima, where a 1200-year-old camphor tree tells the island''s mysteries. Ibukijima, known for its lively fishermen and famous Ibuki iriko. Shonai Peninsula, which juts out into the deep blue Seto Inland Sea, allowing you to enjoy the beauty of multiple islands. Even among the islands of the same Seto Inland Sea, you can enjoy each unique charm.
Check out more videos here! → http://www.my-kagawa.jp/udon-ken/shimatabi.html' where id = 'MGjgNmCG1cZuNep5MqwtF';
update content_bodies set title = 'かがわ極上休日　本島・高見島', description = '昔ながらの趣が漂う町並みが残る本島。江戸時代の隆盛の歴史を残し、ゆっくりと歩いていると、ノスタルジックな風景に時間の流れを忘れてしまいそう。また、島のほとんどが山になっている高見島では、山の急斜面を利用して自然石を積み上げた石垣の集落を見ることができ、懐かしいひとときを感じさせます。
その他の映像はこちら！→http://www.my-kagawa.jp/udon-ken/shimatabi.html' where id = 'AEvwq1ASIjJHkt3jOxuQS';
update content_bodies set title = 'Kagawa''s Exquisite Holiday: Honjima and Takamijima', description = 'Honjima, with its streets that retain the charm of bygone days. 
With a history of prosperity from the Edo period, as you stroll slowly, you might forget the passage of time in the nostalgic scenery. 
On Takamijima, where most of the island is mountainous, you can see villages with stone walls made of natural stones stacked on the steep slopes, evoking a sense of nostalgia. 
For more videos, click here! → http://www.my-kagawa.jp/udon-ken/shimatabi.html' where id = 'B2HSJ7LWYTCmx_J7CuHNU';
update content_bodies set title = '女木島　極上の風が吹く', description = '高松港からフェリーでわずか20分の島。港では風を感じるアートが来る人を優しく出迎えます。島のほぼ中央にある山の頂には大洞窟があり、｢鬼ヶ島｣とも呼ばれる由縁。瀬戸内海の大パノラマが望める展望台では、吹く風が心を軽くしてくれます。' where id = 'VjbigCB_urAboUls4QZNg';
update content_bodies set title = 'Megijima: A Breeze of Perfection', description = 'An island just 20 minutes by ferry from Takamatsu Port. 
At the port, art that captures the wind gently welcomes visitors. 
At the summit of the mountain located almost in the center of the island, there is a large cave, which is the origin of its nickname ''Oni Island.'' 
From the observation deck, where you can enjoy a panoramic view of the Seto Inland Sea, the blowing wind lightens your heart.' where id = 'o4nBtvGPkH-1feGySgbMP';
update content_bodies set title = '直島　極上のクリエイティブ', description = 'あちらこちらにアートが点在し、そして昼も夜もアートな空間に包まれる島。一歩路地に入れば、古から瀬戸内海の海運とともに栄えてきた文化が今なお残り、現代アートと織りなすクリエイティブなさまを垣間見ることができます。' where id = 'ig2V9LcOXb3HUrxlLuVS1';
update content_bodies set title = 'Naoshima: The Ultimate Creative Experience', description = 'A island where art is scattered everywhere, enveloped in an artistic space both day and night. Step into an alley, and you can catch a glimpse of the culture that has thrived alongside the maritime trade of the Seto Inland Sea since ancient times, intertwined with contemporary art.' where id = 'U3REI28EvvKzDg6Ivmi8x';
update content_bodies set title = '高松港　さあ、極上の時間と空間へ', description = '香川では、島を巡る旅はアートを巡る旅でもあります。マザーポート高松港は、アートな島旅の起点。出船、入船で賑わうさまは、旅のワクワク感をふくらませます。カラフルなアートに見送られて、島のアートに会いに出かけましょう。' where id = '3XP6RhdhAYk0XUQ7bzYy1';
update content_bodies set title = 'Takamatsu Port: Now, to an Exquisite Time and Space', description = 'In Kagawa, a journey around the islands is also a journey through art. The mother port, Takamatsu Port, is the starting point for an artistic island adventure. The bustling scene of departing and arriving ships enhances the excitement of travel. Let''s set off to meet the island''s art, waved off by colorful artworks.' where id = 'ECjhxV2MYRY2JJlLEXr8H';
update content_bodies set title = '「撮り旅in 北茨城」1日で観光出来る北茨城', description = '常磐三市（北茨城市・高萩市・いわき市）では、高校生が感じる地域の魅力を企画・撮影・編集して地域のPR動画を作成しました。
