update content_bodies set title = '温泉×筋肉　～茨城の名湯を求めて～　Vol.1湯の網温泉　鹿の湯松屋【字幕付き】', description = '茨城県には各地に名湯・秘湯と言われる温泉があり、ここ北茨城市にもたくさんの名湯が存在します。この動画は、そんな数々の名湯をたくさんの方に知ってもらえるように制作しました。

【湯の網温泉　鹿の湯松屋】
住所：茨城県北茨城市関南町神岡下1435
電話：0293-46-1086（予約）
https://www.jsdi.or.jp/~yunoami/
開湯500年以上の歴史を持つ伝説の鉱泉。鉄分を含んだ赤褐色の湯が特徴で、傷ついた鹿がこの温泉に浸かって傷を癒したと言い伝えられています。
明治初期からある建物も趣があり、ここにいるだけで心も身体も癒されていきます。立ち寄り入浴や日帰り入浴（部屋付き入浴）もやっており、夕食付きの宿泊では、名物のキンキの塩焼きが食べられます。
お風呂は1箇所、男女入れ替えのため、日帰り入浴の場合は、事前にお電話をお願いいたします。

↓その他北茨城市の温泉情報はこちらからどうぞ↓
http://www.kitaibarakishi-kankokyokai.gr.jp/page/dir000062.html

＃茨城温泉
＃名湯
＃秘湯' where id = 'TJ0BLWmVQDRV-TVnPAmkw';
update content_bodies set title = 'Onsen × Muscle - In Search of Ibaraki''s Famous Hot Springs - Vol.1 Yunoami Onsen Shika no Yu Matsuya [With Subtitles]', description = 'Ibaraki Prefecture is home to many famous and hidden hot springs, and there are numerous renowned hot springs in Kitai-baraki City as well. This video was created to introduce these many famous hot springs to a wider audience.

【Yunoami Onsen Shika no Yu Matsuya】
Address: 1435 Kamiyoka, Sekinantown, Kitai-baraki City, Ibaraki Prefecture
Phone: 0293-46-1086 (Reservation)
https://www.jsdi.or.jp/~yunoami/
This legendary mineral spring has a history of over 500 years. It is characterized by its reddish-brown water containing iron, and it is said that injured deer soaked in this hot spring to heal their wounds.
The building, which has been around since the early Meiji period, has a charming atmosphere, and just being here soothes both the mind and body. They offer drop-in bathing and day-use bathing (with room access), and for overnight stays with dinner, you can enjoy the specialty grilled Kinki fish.
There is one bath, and it alternates between men and women, so if you are coming for day-use bathing, please call in advance.

↓ For more information on other hot springs in Kitai-baraki City, please click here ↓
http://www.kitaibarakishi-kankokyokai.gr.jp/page/dir000062.html

#IbarakiOnsen
#FamousHotSprings
#HiddenHotSprings' where id = 'XVmcqT54JMovj5mWYSGj-';
