update content_bodies set title = '今年の夏は磯遊び!!子供も安心♪〜茨城県北茨城市磯原海岸～観光 タイドプール 海の生き物', description = '茨城県北茨城市磯原町にある『磯原海岸』では、
干潮時には普段海の中にある『磯場』が顔を出し、『磯遊び』ができます。

磯場にはたくさんのタイドプールがあり（潮溜まり）が出現し、その中に取り残された生き物を間近で観察することができます！

※この一帯は漁業権が設定されています。
　『アワビ』、『ウニ』、『貝』、『海藻類』等を絶対に取らないでください。密漁となり、海上保安部・警察に罰せられます。
※已经为该地区设定了渔业权
切勿服用“鲍鱼”、“海胆”、“贝类”、“海藻”等。偷猎行为将受到日本海上保安厅和警察的惩罚

干潮時は浅瀬のため、小さなお子様でも安心して、『海の生き物観察』や『貝殻集め』などを楽しむことができます。
小学生のお子様は、磯場でのシュノーケルなど遊びつくせないほどのフィールドがあります！

是非、“着替えをたくさんご持参のうえ”北茨城市『磯原海岸』にお越しください♪

■磯遊び！磯原海岸の詳し情報はこちら
　http://www.kitaibarakishi-kankokyokai.gr.jp/jgcms/admin41037/page_view.php?code=875

