update content_bodies set title = 'This Summer, Enjoy Tide Pooling!! Safe for Kids♪ ~Ibaraki Prefecture, Kitaibaraki City, Isohara Coast~ Tourism, Tide Pools, Marine Life', description = 'At ''Isohara Coast'' in Isohara Town, Kitaibaraki City, Ibaraki Prefecture, 
at low tide, the ''intertidal zone'' that is usually underwater emerges, allowing for ''tide pooling''.

There are many tide pools (pools left by the tide) in the intertidal zone, where you can observe marine creatures up close!

*Fishing rights have been established in this area.
Please do not take ''abalone'', ''sea urchins'', ''shellfish'', ''seaweed'', etc. This is considered poaching and will be punished by the Japan Coast Guard and police.
*Fishing rights have already been established in this area.
Do not take ''abalone'', ''sea urchins'', ''shellfish'', ''seaweed'', etc. Poaching will be punished by the Japan Coast Guard and police.

During low tide, the shallow waters make it safe for small children to enjoy ''marine life observation'' and ''shell collecting''.
Elementary school children will find plenty of fields for activities like snorkeling in the intertidal zone!

Please be sure to bring plenty of changes of clothes and come to ''Isohara Coast'' in Kitaibaraki City!♪

■For more detailed information about tide pooling! Click here for Isohara Coast
http://www.kitaibarakishi-kankokyokai.gr.jp/jgcms/admin41037/page_view.php?code=875

#IbarakiPrefecture #TidePooling #MarineTourism

Automatic translation subtitles are supported.
Turn on subtitles and select a language from Settings→Subtitle→Automatic Translation.
*If you are displaying in Japanese, please turn off subtitles.' where id = 'wk3zM2hA2yUnJF0Askfb4';
update content_bodies set title = '落差60mの名瀑・七ツ滝〜茨城県北茨城市〜を目指してトレッキング', description = '※現在、花園神社第１駐車場からの七ツ滝方面参道は、土砂崩れのため通行止め（侵入禁止）です

七ツ滝は、茨城県北茨城市にある落差60mを誇る圧巻の名瀑です。
『花園山』付近に源を発する『花園川』の侵蝕によって作られた花園渓谷にあり、花園神社奥の院参道を通るルートにあります。

　滝幅は狭いですが、一ノ滝から七ノ滝まで7段になって落下しています。
中央の滝壺は、磯原の天妃山沖に通じているという伝説もあり、海藻がはえ、鮑が生息しているとも信じられておりました。
　昔、かの有名な西山公徳川光圀（水戸黄門）は、滝壺の底を確かめようと、家来に命じて、滝壺に入らせたとの民話も残っています。

■栄蔵室からのルートはこちら
　http://www.kitaibarakishi-kankokyokai.gr.jp/data/doc/1614317072_doc_11_0.pdf

■そのほか、北茨城の観光情報はこちら
　http://www.kitaibarakishi-kankokyokai.gr.jp

■北茨城市の“滝”巡りはこちら
　http://www.kitaibarakishi-kankokyokai.gr.jp/page/page000012.html

 ‪#茨城観光  ‪#七ツ滝 #花園神社' where id = 'r28D16kcFrw2iGUK8Ns51';
update content_bodies set title = 'Trekking to the Famous Waterfall of 60m Drop - Nanatsutaki in Kitaibaraki City, Ibaraki Prefecture', description = '※Currently, the approach to Nanatsutaki from the first parking lot of Hanazono Shrine is closed due to a landslide (no entry).

Nanatsutaki is an impressive waterfall boasting a drop of 60m, located in Kitaibaraki City, Ibaraki Prefecture.
It is situated in the Hanazono Valley, created by the erosion of the ''Hanazono River'' originating near ''Hanazono Mountain'', and is accessible via the approach to the inner shrine of Hanazono Shrine.

Although the width of the waterfall is narrow, it cascades down in seven tiers from the first to the seventh waterfall.
There is a legend that the central pool of the waterfall connects to the sea off the coast of Tenpizuyama in Isohara, where seaweed grows and abalone are believed to inhabit.
In the past, the famous Tokugawa Mitsukuni (Mito Komon) is said to have ordered his retainers to enter the pool to confirm its depth, according to local folklore.

■ Here is the route from Eizō Room
　http://www.kitaibarakishi-kankokyokai.gr.jp/data/doc/1614317072_doc_11_0.pdf

■ For more tourist information about Kitaibaraki, click here
　http://www.kitaibarakishi-kankokyokai.gr.jp

■ For a tour of waterfalls in Kitaibaraki City, click here
　http://www.kitaibarakishi-kankokyokai.gr.jp/page/page000012.html

 ‪#IbarakiTourism  ‪#Nanatsutaki #HanazonoShrine' where id = '2buWhy6J5FRwDy59kBmrr';
update content_bodies set title = '【字幕ON推奨】船が陸を走る祭り!!常陸大津の御船祭～茨城県 北茨城市 大津 おすすめイベント 祭り 次回は2024年～', description = '茨城県北茨城市で“海上での安全”と“豊漁”を祈願するために、5年に1度開催される『常陸大津の御船祭』

大津町に鎮座する佐波波地祇（さわわちぎ）神社の大祭で、1726年頃から始まり、2017年には国指定重要無形民俗文化財に登録された歴史あるお祭りです。

御霊遷しの儀により、神様を神輿に宿し、全長約14ｍ幅約3ｍの祭事船に乗せます。

神輿が乗ったことで『神船』となった船を曳き手たちが曳き、陸路を走ります。

船には“車輪が付いておらず”、ソロバンと呼ばれる木桁の上を走ります。
このような形で神が宿った木造の祭事船が陸路渡御を行う祭りは、全国でも北茨城市だけと言われています。

最大の見せ場は、祭り2日目の本祭りで神船が直角に曲がるところ。
曳き手が神船を大きく左右に揺すり、約7トンの神船が向きを変えます。


船底と木桁との摩擦で白い煙が立ち上がり、集まった観衆から歓声と拍手が湧き起ります。

次回開催は、2024年5月2日（宵祭り）・3日（本祭り）
大迫力の『常陸大津の御船祭』に是非、お越しください！！

■常陸大津の御船祭
　http://www.kitaibarakishi-kankokyokai.gr.jp/page/page000186.html

■北茨城市の宿泊施設はこちら
　http://www.kitaibarakishi-kankokyokai.gr.jp/page/dir000005.html

■お祭り会場（北茨城市大津町）周辺の観光施設情報はコチラ
　http://www.kitaibarakishi-kankokyokai.gr.jp/page/dir000002.html#areaOtsuHirakata' where id = 'CM2zyWH4Flz55k2oiskxh';
update content_bodies set title = '[Subtitles ON Recommended] A Festival Where Ships Run on Land!! Hitachi Otsu''s Mikoshi Festival - Ibaraki Prefecture, Kitaibaraki City, Otsu Recommended Event Festival Next Time in 2024 -', description = 'The ''Hitachi Otsu Mikoshi Festival'' is held once every five years in Kitaibaraki City, Ibaraki Prefecture, to pray for ''safety at sea'' and ''bountiful catches.''

This grand festival is held at the Sawawachigi Shrine in Otsu Town and has a history dating back to around 1726. In 2017, it was registered as an Important Intangible Folk Cultural Asset by the national government.

During the ritual of transferring the spirit, the deity is enshrined in a portable shrine and placed on a ceremonial boat measuring approximately 14 meters in length and 3 meters in width.

With the portable shrine aboard, the boat becomes a ''divine ship'' and is pulled by participants as it runs on land.

The boat does not have ''wheels'' and runs on wooden beams called ''soroban.''
This type of festival, where a wooden ceremonial boat inhabited by a deity travels on land, is said to be unique to Kitaibaraki City in Japan.

The highlight of the festival is on the second day, during the main festival, when the divine ship makes a right-angle turn.
The participants sway the divine ship vigorously from side to side, changing the direction of the approximately 7-ton vessel.

White smoke rises from the friction between the bottom of the boat and the wooden beams, eliciting cheers and applause from the gathered crowd.

The next event will be held on May 2, 2024 (evening festival) and May 3 (main festival).
Please come and experience the powerful ''Hitachi Otsu Mikoshi Festival''!!

■ Hitachi Otsu Mikoshi Festival
　http://www.kitaibarakishi-kankokyokai.gr.jp/page/page000186.html

■ Accommodation facilities in Kitaibaraki City can be found here
　http://www.kitaibarakishi-kankokyokai.gr.jp/page/dir000005.html

■ Information on tourist facilities around the festival venue (Otsu Town, Kitaibaraki City) can be found here
　http://www.kitaibarakishi-kankokyokai.gr.jp/page/dir000002.html#areaOtsuHirakata' where id = '06IX36I7ipBXcv7Z0ico4';
update content_bodies set title = '【日々の疲れは清流の音で癒そう♪】花園渓谷 茨城県 観光 おすすめ 自然 北茨城市', description = '清流音を楽しむリラックス動画です。再生してから目を閉じると、お部屋が渓谷の大自然に早替わり♪日々の暮らしに癒しのひとときをどうぞ＊

