update content_bodies set title = '焚き火を見てぼーっとしている動画【花園オートキャンプ場】茨城県 北茨城市 おすすめ キャンプ場', description = '茨城県北茨城市にある『花園オートキャンプ場』で焚き火を楽しみました。
フィールドで聞こえてくるのは、清流の音とパチパチという焚き火の音のみ。贅沢なひとときを過ごすことができます。

■花園オートキャンプ場施設紹介動画はコチラ
　https://www.youtube.com/watch?v=90qiOEax2mc

？？花園オートキャンプ場ってどんなとこ？？

茨城県は県内に約160箇所のキャンプ場があり、全国で最もフィールドの多いことで有名です。その中で花園オートキャンプ場は、川辺フィールドとして人気が高いです。

オートキャンプサイト(約70㎡)には全サイトAC電源・専用水道付きで初心者にとてもやさしいサイト仕様になっています！
大型車も乗り入れできるモーターホームサイト(150㎡)も有り。
場内にはじゃぶじゃぶ川が流れ、水遊びができるのでファミリーのお客様にも人気です！

また、キャンプ場のそばには『花園川』が流れているため、清流の音を聴きながらのキャンプを楽しむことができます♪
夜になると空いっぱいに星が輝き、キャンパーの心を奪います。。。


是非、花園オートキャンプ場で最高の思い出を♪

■花園オートキャンプ場
　住　　所：北茨城市華川町小豆畑2747
　電話番号：0293-30-0606
　公式  HP：https://www.hanazono-autocamp.com/​
　web予約：https://www.nap-camp.com/ibaraki/10172​
　
