update content_bodies set title = '毎年4月初旬はミズバショウを見に行こう!亀谷地湿原【茨城県 北茨城市 おすすめ観光スポット】', description = '茨城県北茨城市関本町小川エリアにある『亀谷地湿原』。
北茨城ICから花園渓谷方面に車を走らせ約30分。花園渓谷を過ぎた県道27号線沿いを進むと駐車場（路側帯）があります※動画参照
花園花貫県立自然公園内に位置し、山地に発達した湿原です。
サギスゲ、ミズチドリやヒメイチゲが生育しています。この自然を自然を保全しようと、昭和30年代に『ミズバショウ』を栽植しました。その後、管理を市が引き継ぎ昭和62年には約1，000株のミズバショウを植栽しました。
今でも3月下旬には芽吹き、4月上旬から中旬※1にかけて花が咲き、多くの観光客が訪れます。
※1 見頃参考　2020年4月第1週　2021年4月第1週（ここ数年見頃時期が早いです）

