update content_bodies set title = '茨城県 北茨城 野口雨情記念館　しゃぼん玉・七つの子　おすすめ観光スポット', description = '誰もが一度は口ずさんだことのある童謡
『七つの子』や『シャボン玉』などの聞いたことがありませんか？
◆七つの子
　烏 なぜ鳴くの　烏は山に
　可愛い七つの    子があるからよ・・・
◆シャボン玉
　シャボン玉 飛んだ　屋根まで飛んだ
　屋根まで飛んで　　こわれて消えた・・・

全て北茨城市出身の童謡詩人『野口雨情』が作詞したものです。
雨情は
「作者の名が残らなくても良い、作った詩歌が世の人々に永く愛され歌われるなら、それが本望」という信念のもと約3,000もの作品を世に残しました。

そして、その雨情の信念を超え、作詞した童謡や校歌は、雨情の名とともに今もなお歌い継がれています。
野口雨情記念館ではそんな野口雨情の生涯を当時の貴重な資料を展示しながら紹介しています。
誰もが口ずさんだあの子供の頃に、一瞬で戻ることができる『野口雨情記念館』に是非、足を運んでみてはいかがでしょうか？

#茨城 #観光おすすめ #北茨城
#野口雨情

■野口雨情記念館公式HP
　http://www.ujokinenkan.jp

■野口雨情記念館アクセス
　https://goo.gl/maps/uCySRi3Yd29fnM8x6

