update content_bodies set title = '【世界遺産 十石堀】プチトレッキング・茨城県 北茨城市 おすすめ観光スポット', description = '世界かんがい施設遺産の『十石堀』をプチトレッキング♪
駐車場とトイレが整備されている『十石堀親水公園』に車を停車し、そこから『瀧ノ沢水門』まで往復約１時間のお手軽コース。
標高が高いため眺望が良い箇所や両側とも土の壁に覆われている自然が作り上げた遊歩道など、楽しみながら歩くことができます。近年は、ファミリーでトレッキングを楽しむ層も増えています。4歳あたりから最後まで歩くことのできるコースで小学校低学年生までは大冒険のフィールドです！！
日棚分水工前は開けているので、チェアとお弁当を持参すれば、大自然の中での軽食も可能です。
県北ロングトレイルのコースとしても注目されています。

■十石堀
