update content_bodies set title = '家で簡単＊あんこうどぶ汁発祥の地が教える！絶品 あんこう鍋の作り方 茨城県 北茨城市', description = 'あんこう鍋の本場『北茨城市』
地元の港で水揚げされた″あんこう鍋”や“水産加工品”を取り扱う通販サイトであんこう鍋を取り寄せてみました。

冬になると、首都圏のスーパーで時々売られているあんこう。臭みがありそうなイメージだし、作り方もわからないし・・・
そんなことないんです！『あんこう鍋』って意外と簡単なんですよ！

①購入したあんこうを流水解凍します（冷凍あんこうの場合）
②具材を切ります（白菜、ネギ、ニンジン、しいたけ、えのき、豆腐などなどお好きな具材をどうぞ！）
③あん肝を弱火で炒めます（ペーストになっている場合はお湯に溶かし入れる）
④味噌を入れてひと煮立ちさせます
⑤あんこうを入れて、お酒を少々いれます
⑥②で切った具材を盛りつけます
⑦すべての具材に火がとおったら・・・完成です！！
⑧〆はごはんと小ねぎを入れて、雑炊に♪♪

ぜひ、取り寄せに挑戦して、ご自宅で本場の味を楽しんでくださいね♪

■お取り寄せサイト：きたいばマルトクショップ
　http://www.marutokushop.jp/

■お取り寄せ品：鍋用あんこう（冷凍）

