update content_bodies set title = '【圧巻の茅葺き屋根】浄蓮寺・浄蓮寺渓谷／北茨城 観光 おすすめ観光スポット', description = '茨城県北茨城市華川町にある『浄蓮寺』です。
慈覚大師が奥州山寺の開基後、この地により開基したと伝えられています。
浄蓮寺の山門や本堂を左拝して、日陰の道を進むと『浄蓮寺渓谷』に行き着きます。修行僧が彫ったという33体の観音像が各所に刻まれています。
『浄蓮寺渓谷』は、大きな岩が多く点在しており、紅葉の時期には紅葉の朱色と岩肌からなるコントラストが映え、美しい景観が楽しむことができます♪

