update content_bodies set title = '日本一のあんこう鍋／茨城県 北茨城市 絶品 鍋 通販', description = '**あんこう鍋発祥の地  茨城県北茨城市**
２年連続 鍋１GPで日本一に輝くなど、全国に認められた本場のあんこう鍋。

あん肝を炒り、作りあげる濃厚“みそ味”が特徴です！
北茨城市の北部に位置する『平潟港』の漁師が、「船上で水を節約しながら、暖を取ることのできる料理」として食べ始められたのが「あんこう・どぶ汁」と言われています。どぶ汁は、あんこうと野菜からでる水分のみで作ります。そこにだし汁を加えて作るものがあんこう鍋であることから、“あんこう鍋のルーツ”と言われています。

そんなあんこう鍋発祥の地北茨城市が毎年開催している『全国あんこうサミット』（公式ホームページ：http://www.kitaibarakishi-kankokyokai.gr.jp/page/dir000777.html）。
2021年は、新型コロナウイルス感染症の影響から中止となり、多くの方から落胆の声をいただいたため、今回の、“あんこう鍋”動画を制作しました。

♪あんこう鍋のお取り寄せもできます♪特集ページはコチラからどうぞ↓♪
　http://www.kitaibarakishi-kankokyokai.gr.jp/page/page000568.html

■北茨城で本場あんこう鍋を食べたい方はこちらからどうぞ♪
　http://www.kitaibarakishi-kankokyokai.gr.jp/page/dir000710.html

■その他、北茨城の観光情報はこちら：北茨城市観光協会公式ホームページ
