update content_bodies set title = '[Trekking & Autumn Foliage Spot: Jikkohori & Okita Valley] Route Guide Video from Kita-Ibaraki IC to Okita Valley - Recommended Ibaraki Sightseeing', description = 'Jikkohori and Okita Valley, popular tourist spots in Kita-Ibaraki City, Ibaraki Prefecture.
This is a route guide video from ''World Irrigation Heritage Jikkohori'' to ''Okita Valley'' and ''Hanazono Valley'' from the Joban Expressway Kita-Ibaraki IC! Please watch it to check the road width and access routes.

You can park at the ''Shinsui Park'' located in the center of Jikkohori and enjoy a short trekking experience to the Takinosawa Water Gate. There are spots with great views and areas surrounded by earthen walls on both sides, making it enjoyable for children to walk.
For preschoolers and lower-grade elementary school students, it is sure to provide a sense of adventure! ♪
Jikkohori: http://www.kitaibarakishi-kankokyokai.gr.jp/page/page000570.html

Okita Valley is a popular sightseeing spot where you can enjoy fresh greenery and autumn foliage from the car window. By proceeding along Prefectural Road 22 that runs along the valley and turning right at the front of Koyama Dam, you can also extend your visit to the popular autumn foliage spot ''Hanazono Valley'' in the city.

