update content_bodies set title = '徳川斉昭、水戸黄門・野口雨情が登った低山 茨城 観光 おすすめ', description = '茨城県北茨城市磯原町にある天妃山・弟橘媛神社（てんぴさん・おとたちばなひじんじゃ）

かの有名な徳川光圀（水戸黄門）と徳川斉昭のゆかりがある低山。
神社からさらに登ると、光圀が腰かけたとされる石があります。
『七つの子』、『しゃぼん玉』などの童謡で知られる野口雨情も作詞に悩んだ際は、よく天妃山に登りそこからの景色を眺めていたそうです。
雨情は住所を聞かれた際、「住所は磯原海岸です！」と答えていたほど、磯原海岸・天妃山には愛着を持っていたとされています。

北茨城市にお越しの際は、両名が愛した磯原海岸の景色を是非ご覧ください
♪

■アクセス
