update content_bodies set title = '【茨城県逆さ紅葉の名所 】水沼ダム〜ダム釣り・紅葉名所・トレッキングを楽しもう〜茨城 観光 おすすめ', description = '茨城県北茨城市にある水沼ダムです。

花園川からなるダムで紅葉が美しく、春はカタクリ、夏はキツネノカミソリが群生しています。湖面に映り込む紅葉や新緑が美しく、近年、台湾観光客を中心に注目されているスポットです。

