update content_bodies set title = '【花園神社】子宝・安産の大杉〜北茨城 茨城 観光 おすすめ スポット〜御朱印', description = '茨城県北茨城市にある花園神社です。
平安時代に初代征夷大将軍 坂上田村麻呂が創建したと伝えられている歴史ある神社です。
樹齢800年の大杉、高野槇の老木が立ち並び、木々の緑に朱塗りの仁王門、拝殿、本殿が映える様は荘厳。

境内に立つ古杉は、子を授かり臨月を迎えた母の姿に似ていることから『子宝・安産の杉』として親しまれ、全国から多くの参拝客が訪れます。

