update content_bodies set title = 'Hanazono Shrine: Great Cedar for Childbirth and Safe Delivery - Recommended Sightseeing Spot in Kitaibaraki, Ibaraki - Goshuin', description = 'Hanazono Shrine is located in Kitaibaraki City, Ibaraki Prefecture.
It is a historic shrine said to have been founded by the first shogun of the Heian period, Sakanoue no Tamuramaro.
The 800-year-old great cedar and ancient Koya cedar trees stand in a row, and the vermilion Nio gate, worship hall, and main shrine stand out majestically against the greenery of the trees.

The ancient cedar standing in the precincts is beloved as the ''Cedar for Childbirth and Safe Delivery'' because it resembles a mother who is about to give birth, attracting many worshippers from all over the country.

■ For detailed directions from Kitaibaraki IC, please watch this video♪
　https://www.youtube.com/watch?v=2RC7xzogEW4&t=10s
　There are parking lots from the first to the third, accommodating about 100 cars. Large buses can also park and turn around.

■ Here is the Kitaibaraki Tourism Association HP
　http://www.kitaibarakishi-kankokyokai.gr.jp

■ Here is the Kitaibaraki Tourism Association LINE
　http://www.kitaibarakishi-kankokyokai.gr.jp/page/page000559.html

