update content_bodies set title = '沢登り・紅葉の名所〜猿ヶ城渓谷【北茨城市 観光 名所 おすすめスポット】', description = '茨城県北茨城市にある猿ヶ城渓谷です。

猿ヶ城渓谷は、花園渓谷から県道27号線をさらに塙町方面に進み、猿ヶ城林道周辺をいいます。
沢歩きや車窓からの紅葉を楽しむことができる人気の観光スポットです。

北茨城ICから車を走らせると、手前から浄蓮寺渓谷、花園渓谷、猿ヶ城渓谷の順に渓谷があります。
１番山間部に位置する猿ヶ城渓谷は市内の紅葉としては最も早く例年10月下旬に色づき始めます。
また、猿ヶ渓谷は花園渓谷終盤の『箱滝方面』の看板横から入渓することができ、『箱滝』や『落雲の滝』、『千猿の滝』を越える沢登りができます（上級者向け）。
渓谷MAPはこちら
http://www.kitaibarakishi-kankokyokai.gr.jp/page/page000012.html
また、『千猿の滝』は猿ヶ城林沿いに路側帯があり、一時駐車し、滝下まで下ることができます（動画中で紹介しています！）

北茨城ICからの詳しい行き方はこちらの動画をご覧ください♪
https://www.youtube.com/watch?v=2RC7xzogEW4&t=10s

