update content_bodies set title = '[Live Painting] Welcome Back Okayama Castle - Paint It Gold and Black', description = 'New Okayama Castle PR site https://kin-ujo.jp/

On November 3, 2022, Okayama Castle is coming back.
Draped in new gold and black, it returns to the city of Okayama.

As the "Reiwa Major Renovation" progresses steadily,
we expressed our feelings for Okayama Castle through art and song.
Live painting on a gold folding screen by local illustrator Asuka Ezaki.
Watch as the historical castle lords and their wives are dynamically depicted in black ink.

The song used in the Okayama Castle MV series
has been rearranged into a Japanese-style R&B for this third installment.
The high-tone voice of Masatora Makino, who won the "Hamonepu 2021 Summer Competition,"
resonates throughout.

Like the Asahi River flowing beside Okayama Castle,
time flows and is passed on to the next generation.
Witness a moment in history.
See you at the new Okayama Castle on November 3.

* The first two installments of the series are also being released with great acclaim!
