update content_bodies set title = '千年の歴史を持つ神社「備前国総社宮」　～お祭り・神輿担ぎ体験～', description = '平安時代に創建され、岡山備前128の神社のご祭神を合祀した神社。ここにお参りすると一度に全ての神社にお参りしたことになるといわれています。

　日本の伝統芸能、岡山を感じていただけるコンテンツを紹介します。

　鳥居をくぐって見える拝殿は1992年に放火で焼失後、創建当時の平安時代の社殿を復元し再建されたもので、全国でもここにしかない美しい拝殿になります。また、龍ノ口という山の麓に位置し日本でも有数のパワースポットとなっています。

　ここでは、日本に古くから伝わるお祭り、お神輿を担ぐ伝統文化体験、獅子舞奉納、岡山の食を味わえる屋台出店など特別な体験を演出することが出来ます。' where id = 'sHDsVsW--lqxmHG0nN39x';
update content_bodies set title = 'A Shrine with a Thousand-Year History: Bizen Kuni Sōja Shrine - Festival and Mikoshi Carrying Experience', description = 'Founded in the Heian period, this shrine enshrines the deities of 128 shrines in Okayama Bizen. It is said that by visiting here, one has paid homage to all the shrines at once.

We introduce content that allows you to experience traditional Japanese performing arts and the essence of Okayama.

The hall of worship visible through the torii gate was rebuilt in 1992 after being destroyed by arson, restoring the original Heian period structure, making it a beautiful hall of worship unique in the country. Additionally, it is located at the foot of Mount Ryūnoguchi, making it one of Japan''s renowned power spots.

Here, you can enjoy special experiences such as traditional cultural activities like carrying the mikoshi, lion dance offerings, and food stalls where you can taste Okayama''s cuisine.' where id = 'vuLZTCzAHFsgetyusMVwj';
update content_bodies set title = '【烏城公園・岡山城】2021桜 ～空旅時間～ 岡山市を感じるスカイウォーク', description = '岡山市の桜スポットを空から眺めるドローン映像です。
新型コロナウイルスの影響で花見を自粛された方、花見に行けなかった方々も、岡山市内で咲き誇る桜を見ていただき、お花見気分を満喫してください！

黒い下見板張りの外観から別名「烏城（うじょう）」と呼ばれている岡山城。周辺は「烏城公園」として整備され、春にはきれいな桜を楽しむこともできます。天守閣前広場で黒い外観と桜のコントラストを楽しんだ後は、天守閣から市内を眺めるのがオススメ。（別途、天守閣への入館料が必要です。）


