update content_bodies set title = '[Okayama Castle & Kōjō Park] 2021 Cherry Blossoms ~Sky Travel Time~ A Skywalk to Experience Okayama City', description = 'This is a drone video capturing the cherry blossom spots in Okayama City.
For those who refrained from cherry blossom viewing due to the impact of the COVID-19 pandemic, or those who couldn''t go, please enjoy the beautiful cherry blossoms blooming in Okayama City and indulge in the hanami atmosphere!

Okayama Castle, also known as ''Ujō'' due to its black wooden exterior, is surrounded by ''Kōjō Park,'' where you can enjoy beautiful cherry blossoms in spring. After enjoying the contrast of the black exterior and cherry blossoms in the plaza in front of the main keep, it is recommended to view the city from the top of the castle. (Please note that there is a separate admission fee for entering the main keep.)

