近水園は足守藩主木下家の庭園で、池庭は単純な地割がなされ、モミジやサクラ、エノキが池を囲み、池中に鶴島・亀島の二島を巧に配しています。そして、山のふもとから池面にのり出すように、吟風閣が建ち、水面に影を映しています。池畔にあるこの吟風閣の造りなど、地方まれな情緒をたたえており、吟風閣からの眺めが一番美しいとされます。

